async function loadDatasetExerciseCatalog(){
  try {
    const response=await fetch('./dataset-exercises.json'); if(!response.ok)throw new Error('Catálogo no disponible');
    const records=await response.json();
    const recordsById=new Map(records.map((record)=>[String(record.id),record]));
    const muscleFor=(r)=>{const s=`${r.bodyPart} ${r.category} ${r.target} ${r.muscleGroup}`.toLowerCase();if(/chest|pectoral/.test(s))return'chest';if(/back|lats|trap/.test(s))return'back';if(/shoulder|deltoid/.test(s))return'shoulders';if(/biceps/.test(s))return'biceps';if(/triceps/.test(s))return'triceps';if(/upper arms/.test(s))return/biceps/.test(r.name.toLowerCase())?'biceps':'triceps';if(/forearm|lower arms/.test(s))return'forearms';if(/quad|thigh|leg/.test(s))return'quads';if(/hamstring/.test(s))return'hamstrings';if(/glute|hip/.test(s))return'glutes';if(/calf|lower legs/.test(s))return'calves';if(/neck/.test(s))return'shoulders';return'core';};
    const equipmentFor=(r)=>r.equipmentLabel||'Peso corporal';
    for(const r of records){const id=`gymvisual-${r.id}`;EXERCISES.push({id,name:datasetExerciseName(r),datasetOriginalName:r.name,muscle:muscleFor(r),secondary:[],equip:equipmentFor(r),glyph:'◇',sets:3,reps:'8–12',rest:90,focus:`${datasetTerm(r.target||r.category)} · ${datasetTerm(r.category)}`,cues:[r.instructions||'Sigue la secuencia ilustrada y trabaja con un rango que controles.'],datasetImage:r.image,datasetGif:r.gif,datasetInstructions:r.instructions,datasetSteps:r.steps,datasetAttribution:r.attribution,datasetMuscleGroup:r.muscleGroup,datasetTarget:r.target});}
    for(const exercise of EXERCISES){
      const mediaId=BASE_EXERCISE_MEDIA_IDS[exercise.id],media=mediaId&&recordsById.get(mediaId);
      if(!media)continue;
      exercise.datasetImage=media.image;exercise.datasetGif=media.gif;exercise.datasetAttribution=media.attribution;
      exercise.datasetMediaVariant=BASE_MEDIA_VARIANT_IDS.has(exercise.id);exercise.datasetMediaName=datasetExerciseName(media);
    }
    renderBodyWeeklySummary();renderBodyMap();renderExercises(); $('#exercise-count').title=`${records.length} ejercicios del conjunto Gym visual más movimientos originales de Forja`;
  } catch(error) { console.error('No se pudo cargar el catálogo ampliado:',error); }
}
