function updateTheme() {
  const light = profile.data.theme === 'light';
  const accent = ['lemon', 'blue', 'violet', 'orange', 'red'].includes(profile.data.accent) ? profile.data.accent : 'lemon';
  document.body.classList.toggle('light-mode', light);
  document.body.dataset.accent = accent;
  document.documentElement.style.colorScheme = light ? 'light' : 'dark';

  const themeColor = document.querySelector('meta[name="theme-color"]');
  if (themeColor) themeColor.content = light ? '#f4f6f1' : '#101412';
  const manifest = document.querySelector('link[rel="manifest"]');
  if (manifest) manifest.href = light ? './manifest-light.json' : './manifest.json';

  $$('[data-accent-choice]').forEach((button) => {
    const active = button.dataset.accentChoice === accent;
    button.classList.toggle('active', active);
    button.setAttribute('aria-pressed', String(active));
  });
  $('#theme-toggle').textContent = light ? '☾' : '☼';
  $('#theme-toggle').setAttribute('aria-label', light ? 'Activar tema oscuro' : 'Activar tema claro');
  $('#theme-toggle').setAttribute('aria-pressed', String(light));
  $('#theme-toggle').title = light ? 'Cambiar a tema oscuro' : 'Cambiar a tema claro';
}
