const BODY_MAP_GROUPS = {
  front: {
    chest: ['chest', 'upper-chest', 'lower-chest'],
    shoulders: ['deltoids', 'front-deltoid', 'rotator-cuff'],
    biceps: ['biceps'], forearms: ['forearm'],
    core: ['abs', 'upper-abs', 'lower-abs', 'obliques', 'serratus'],
    quads: ['quadriceps', 'inner-quad', 'outer-quad', 'hip-flexors'],
    calves: ['calves', 'tibialis', 'ankles'], neck: ['neck'], feet: ['feet'], adductors: ['adductors'],
  },
  back: {
    shoulders: ['deltoids', 'rear-deltoid', 'rotator-cuff'],
    back: ['upper-back', 'lower-back', 'trapezius', 'upper-trapezius', 'lower-trapezius', 'rhomboids', 'serratus'],
    triceps: ['triceps'], forearms: ['forearm'], glutes: ['gluteal'],
    hamstrings: ['hamstring'], calves: ['calves', 'tibialis', 'ankles'], neck: ['neck'], feet: ['feet'], adductors: ['adductors'],
  },
};
